const upstream = $input.first().json;

const output = upstream.response ?? upstream.output ?? '{}';

const plan = JSON.parse(
  String(output)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim()
);

const base = {
  campaign_id: 'camp-' + $execution.id,
  campaign_name: plan.campaign_name ,
  campaign_type: plan.campaign_type || '',
  target_tier: plan.target_tier || 'Gold',
  channel: plan.channel || 'email',
  send_date: plan.send_date || '',
  qa_attempt: 0,
  max_qa_attempts: 3
};

const planJson = JSON.stringify(plan, null, 2);

const result = {
  ...base,
  plan,
  plan_ready: true,
  plan_json: planJson,
  s3_key_plan: `plan/plan-${base.campaign_id}.json`
};

const binaryData = Buffer.from(planJson, 'utf8');

return [{
  json: result,
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'application/json',
      fileName: `plan-${base.campaign_id}.json`,
      fileExtension: 'json'
    }
  }
}];

