const base = $('Build + Prepare plan.json').first().json;

// Get AI response
const input = $input.first().json;
const output = input.response || input.output;

if (!output) {
  throw new Error('AI response is missing. Expected `response` or `output`.');
}

let content;

try {
  if (typeof output === 'object' && output !== null) {
    content = output;
  } else {
    const cleanedOutput = String(output)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    content = JSON.parse(cleanedOutput);
  }
} catch (e) {
  throw new Error(
    `AI response is not valid JSON: ${e.message}`
  );
}

if (
  !content ||
  typeof content !== 'object' ||
  Array.isArray(content)
) {
  throw new Error('AI response must be a JSON object.');
}

let prevAttempt = 0;

try {
  prevAttempt = Number(
    $('Build + Prepare qa-report.json').first().json.qa_attempt || 0
  );
} catch (e) {
  prevAttempt = 0;
}

const attempt = prevAttempt + 1;

content = {
  subject: content.subject || '',
  preview_text: content.preview_text || '',
  body: content.body || '',
  cta_text: content.cta_text || '',
  cta_url: content.cta_url || '',
  tone: content.tone || '',
  word_count: Number(content.word_count || 0),
  attempt: attempt
};

const contentJson = JSON.stringify(content, null, 2);

const result = {
  ...base,
  content,
  content_ready: true,
  content_json: contentJson,
  s3_key_content: `content/content-${base.campaign_id}-v${attempt}.json`,
  qa_attempt: attempt
};

const binaryData = Buffer.from(contentJson, 'utf8');

return [
  {
    json: result,
    binary: {
      data: {
        data: binaryData.toString('base64'),
        mimeType: 'application/json',
        fileName: `content-${base.campaign_id}-v${attempt}.json`,
        fileExtension: 'json'
      }
    }
  }
];

