const base = $('Build + Prepare content.json').first().json;

const input = $input.first().json;
const output = input.response || input.output;

if (!output) {
  throw new Error(
    'QA AI response is missing. Expected `response` or `output`.'
  );
}

let qaReport;

try {
  if (typeof output === 'object' && output !== null) {
    qaReport = output;
  } else {
    const cleanedOutput = String(output)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    qaReport = JSON.parse(cleanedOutput);
  }
} catch (e) {
  throw new Error(
    `QA AI response is not valid JSON: ${e.message}`
  );
}

if (
  !qaReport ||
  typeof qaReport !== 'object' ||
  Array.isArray(qaReport)
) {
  throw new Error(
    'QA AI response must be a JSON object.'
  );
}

const passed =
  qaReport.passed !== undefined
    ? qaReport.passed === true
    : qaReport.qa_passed === true;

const score = Number(
  qaReport.score !== undefined
    ? qaReport.score
    : (
        qaReport.qa_score !== undefined
          ? qaReport.qa_score
          : 0
      )
);

let attempt;

if (base.qa_attempt !== undefined && base.qa_attempt !== null) {
  attempt = Number(base.qa_attempt);
} else if (
  qaReport.attempt !== undefined &&
  qaReport.attempt !== null
) {
  attempt = Number(qaReport.attempt);
} else {
  attempt = 1;
}

qaReport = {
  passed,
  score,
  attempt,
  rules_checked: Number(
    qaReport.rules_checked || 0
  ),
  rules_passed: Number(
    qaReport.rules_passed !== undefined
      ? qaReport.rules_passed
      : 0
  ),
  issues: Array.isArray(qaReport.issues)
    ? qaReport.issues
    : [],
  fix_suggestions: Array.isArray(
    qaReport.fix_suggestions
  )
    ? qaReport.fix_suggestions
    : [],
  checked_at:
    qaReport.checked_at ||
    new Date().toISOString()
};

const qaReportJson = JSON.stringify(
  qaReport,
  null,
  2
);

const result = {
  ...base,
  qa_report: qaReport,
  qa_passed: qaReport.passed === true,
  qa_score: Number(qaReport.score),
  qa_report_json: qaReportJson,
  s3_key_qa:
    `qa-report/qa-${base.campaign_id}-attempt${qaReport.attempt}.json`
};

const binaryData = Buffer.from(
  qaReportJson,
  'utf8'
);

return [
  {
    json: result,
    binary: {
      data: {
        data: binaryData.toString('base64'),
        mimeType: 'application/json',
        fileName:
          `qa-${base.campaign_id}-attempt${qaReport.attempt}.json`,
        fileExtension: 'json'
      }
    }
  }
];

const i=$('Build + Prepare qa-report.json').first().json;
return [{json:{
  ...i,
  final_status:'AWAITING_SIGN_OFF',
  qa_attempts_used:i.qa_attempt,
  approval_summary:[
    `Campaign: ${i.campaign_name}`,
    `Campaign ID: ${i.campaign_id}`,
    `Subject: ${i.content?.subject || 'N/A'}`,
    `QA Score: ${i.qa_score || 0}/100`,
    `QA Attempts: ${i.qa_attempt}`,
    'Status: Ready for human sign-off'
  ].join('\n')
}}];

