const input=$('Build + Prepare qa-report.json').first().json;
const max=Number(input.max_qa_attempts||3);
const current=Number(input.qa_attempt||1);
const left=max-current;
return [{json:{
  ...input,
  attempts_left:left,
  max_attempts_reached:left<=0,
  retry_message:left>0
    ? `QA failed. Attempt ${current}/${max}. Retrying Content Agent with QA feedback.`
    : `QA failed after ${max} attempts. Escalating for manual review.`
}}];

const i=$input.first().json;
return [{json:{
  ...i,
  final_status:'ESCALATED',
  reason:`QA failed after maximum ${i.max_qa_attempts || 3} attempts`,
  qa_attempts_used:i.qa_attempt,
  last_qa_score:i.qa_score,
  last_qa_issues:i.qa_report?.issues || [],
  escalated_at:new Date().toISOString(),
  action_required:'Manual content review and QA sign-off required'
}}];
